+fn get_active_running_sessions(
+    state: &RemoteGatewayState,
+    cache: &WorkspaceSnapshotCache,
+) -> Vec<RemoteTerminalSession> {
+    let active = state.active_selection.read().clone();
+    let Some(active_sel) = active else {
+        return Vec::new();
