+    let state = Arc::new(RemoteGatewayState::new(
+        Arc::clone(&terminal_service),
+        registry.clone(),
+    ));
+
+    *state.config.write() = RemoteGatewayConfig {
+        mode: RemoteNetworkMode::LocalNetwork,
+        port: 0,
+        allow_control: true,
+    };
